function [p_ref_i, p_ref_o] = get_path_range(p_ref, D)
N = size(p_ref, 2);
p_ref_i = p_ref;
p_ref_o = p_ref;

det_ref = p_ref - [p_ref(:, end), p_ref(:, 1:end-1)];

for idx = 1:N
    dir = [0, -1; 1, 0]*det_ref(:, idx)/norm(det_ref(:, idx));
    p_ref_i(:, idx) = p_ref_i(:, idx) + dir*D;
    p_ref_o(:, idx) = p_ref_o(:, idx) - dir*D;
end
% [min_dist, min_idx] = min(vecnorm(det_ref))
for idx = N:-1:1
    
    if(min(vecnorm(p_ref - p_ref_i(:, idx))) < D-1e-3 || isnan(p_ref_i(1, idx)))
        p_ref_i(:, idx) = [];
    end
    if(min(vecnorm(p_ref - p_ref_o(:, idx))) < D-1e-3 || isnan(p_ref_o(1, idx)))
        p_ref_o(:, idx) = [];
    end
end

% [~, i_idx] = sort(atan2(p_ref_i(2, :), p_ref_i(1, :)));
% p_ref_i = p_ref_i(:, i_idx);
% 
% [~, o_idx] = sort(atan2(p_ref_o(2, :), p_ref_o(1, :)));
% p_ref_o = p_ref_o(:, o_idx);

end


function s = readdata(filename, range)
qrData = importdata(filename); 
for i = 1: length(qrData.colheaders)
    if(nargin == 1)
        eval(['s.', eval(['qrData.colheaders{', num2str(i),'}']), '= qrData.data(:, ', num2str(i), ');']);
    else
        eval(['s.', eval(['qrData.colheaders{', num2str(i),'}']), '= qrData.data(range, ', num2str(i), ');']);
    end
end
T = 0.05;
s.vx = [s.px(2:end,1) - s.px(1:end-1,1); s.px(end,1) - s.px(end-1,1)]/T;
s.vy = [s.py(2:end,1) - s.py(1:end-1,1); s.py(end,1) - s.py(end-1,1)]/T;

s.vb =  zeros(length(s.vx), 2);

for i=1:length(s.vx)
    vg = [s.vx(i); s.vy(i)];
    R = [cos(s.yaw(i)), -sin(s.yaw(i)); sin(s.yaw(i)), cos(s.yaw(i))]';
    s.vb(i, :) = (R*vg)';
end

s.vx = [s.px(2:end,1) - s.px(1:end-1,1); s.px(end,1) - s.px(end-1,1)]/T;
s.vy = [s.py(2:end,1) - s.py(1:end-1,1); s.py(end,1) - s.py(end-1,1)]/T;

s.aaim_x = [s.vaim_x(2:end,1) - s.vaim_x(1:end-1,1); s.vaim_x(end,1) - s.vaim_x(end-1,1)]/T;
s.aaim_y = [s.vaim_y(2:end,1) - s.vaim_y(1:end-1,1); s.vaim_y(end,1) - s.vaim_y(end-1,1)]/T;
s.aset_x = [s.vset_x(2:end,1) - s.vset_x(1:end-1,1); s.vset_x(end,1) - s.vset_x(end-1,1)]/T;
s.aset_y = [s.vset_y(2:end,1) - s.vset_y(1:end-1,1); s.vset_y(end,1) - s.vset_y(end-1,1)]/T;

for i = 2: length(s.aaim_x)
    if(s.aaim_x(i) == 0)
        s.aaim_x(i) = s.aaim_x(i-1);
    end
    if(s.aaim_y(i) == 0)
        s.aaim_y(i) = s.aaim_y(i-1);
    end
    if(s.aset_x(i) == 0)
        s.aset_x(i) = s.aset_x(i-1);
    end
    if(s.aset_y(i) == 0)
        s.aset_y(i) = s.aset_y(i-1);
    end
end

s.t = (0:(size(s.px, 1)-1))*T;
s.a_set_norm = vecnorm([s.aset_x, s.aset_y]')';

end


function [count] = getcount(a1, a2, a3, vals)
count = zeros(size(vals, 2), 3);
for i = 1:size(vals, 2)
    count(i, 1) = sum(a1 < vals(i));
    count(i, 2) = sum(a2 < vals(i));
    count(i, 3) = sum(a3 < vals(i));
end
end